values
  ('sapporo-001', 'sapporo', 'spot', '오도리 공원 (Odori Park)', '오도리 공원 (Odori Park)', null, null, null, 'reviewed', '{"오도리 공원 (Odori Park)","공원 산책 및 구운 옥수수 맛보기 🌽","Odori Park, Sapporo"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '공원 산책 및 구운 옥수수 맛보기 🌽', '삿포로 TV타워를 배경으로 완벽한 인생샷을 남길 수 있는 최고 명소입니다! 공원 내 포장마차(토키비 웨건)에서 파는 노릇노릇한 구운 옥수수와 버터 감자는 삿포로 여름의 상징이니 벤치에 앉아 꼭 드셔보세요.', 'Odori Park, Sapporo', '00:00', '24:00', null, null, null, null, 10),
  ('sapporo-002', 'sapporo', 'spot', '모이와야마 전망대 (Mt. Moiwa Ropeway)', '모이와야마 전망대 (Mt. Moiwa Ropeway)', null, null, null, 'reviewed', '{"모이와야마 전망대 (Mt. Moiwa Ropeway)","일본 3대 야경 로프웨이 탑승 🚡","Mt. Moiwa Ropeway, Sapporo"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.7', '일본 3대 야경 로프웨이 탑승 🚡', '해발 531m 정상에서 감상하는 삿포로 시내의 360도 은하수 야경은 압도적입니다. 산 정상의 ''사랑의 종''에서 하트 자물쇠를 걸거나 종을 함께 울리며 황홀하고 로맨틱한 삿포로의 밤을 연출해보세요.', 'Mt. Moiwa Ropeway, Sapporo', '10:30', '22:00', null, null, null, null, 20),
  ('sapporo-003', 'sapporo', 'noodle', '스프카레 스아게플러스 (Suage+)', '스프카레 스아게플러스 (Suage+)', null, null, null, 'reviewed', '{"스프카레 스아게플러스 (Suage+)","닭꼬치(시레토코도리) 스프카레 (약 1,400엔)","Suage+, South 4 West 5, Sapporo"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '닭꼬치(시레토코도리) 스프카레 (약 1,400엔)', '가라쿠(GARAKU)의 줄이 너무 길어 포기해야 할 때 1티어 대안지! 숯불에 구운 닭고기가 꼬치에 꽂혀 나와 먹기 편하고 국물이 대단히 깊고 얼큰합니다. 가라쿠 바로 근처에 본점과 2호점이 붙어있어 웨이팅 분산이 빠릅니다.', 'Suage+, South 4 West 5, Sapporo', '11:30', '21:30', null, null, null, null, 30),
  ('sapporo-004', 'sapporo', 'noodle', '스프카레 트레져 (TREASURE)', '스프카레 트레져 (TREASURE)', null, null, null, 'reviewed', '{"스프카레 트레져 (TREASURE)","함바그 스프카레 (약 1,350엔)","스프카레 TREASURE, Sapporo"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.4', '함바그 스프카레 (약 1,350엔)', '스프카레 맛집 가라쿠(GARAKU)의 자매 브랜드 식당입니다. 비법 베이스 스프와 맛이 매우 유사하여 가라쿠 웨이팅이 감당이 안 될 때 바로 갈 수 있는 훌륭한 대안입니다. 철판 함바그 토핑이 대단히 잘 어울립니다.', '스프카레 TREASURE, Sapporo', '11:30', '20:30', null, null, null, null, 40),
  ('sapporo-005', 'sapporo', 'meat', '징기스칸 아루코 (Alco)', '징기스칸 아루코 (Alco)', null, null, null, 'reviewed', '{"징기스칸 아루코 (Alco)","생양고기 어깨살 & 양갈비 (약 1,200엔)","Arco Jingisukan, Sapporo"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '생양고기 어깨살 & 양갈비 (약 1,200엔)', '다루마 본점과 스스키노 골목의 다른 지점에 줄이 수십 미터 서 있을 때 갈 수 있는 숨겨진 골목 생양고기 최강 대안! 고기 질이 다루마만큼 훌륭하고 가격도 착합니다. 아늑한 다찌석 위주로 조용히 맥주와 곁들이기 좋습니다.', 'Arco Jingisukan, Sapporo', '17:00', '22:00', null, null, null, null, 50),
  ('sapporo-006', 'sapporo', 'noodle', '라멘 요시야마 쇼텐 (Yoshiyama Shouten)', '라멘 요시야마 쇼텐 (Yoshiyama Shouten)', null, null, null, 'reviewed', '{"라멘 요시야마 쇼텐 (Yoshiyama Shouten)","매운 참깨 미소 라멘 (약 950엔)","Yoshiyama Shouten, Sapporo"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.3', '매운 참깨 미소 라멘 (약 950엔)', '라멘 신겐의 1~2시간 이상 웨이팅이 부담스러우시다면 삿포로역 ESTA 공화국이나 스스키노 빌딩 지하의 요시야마 쇼텐으로 가세요! 볶은 참깨의 고소함 and 삿포로 정통 미소의 감칠맛이 폭발하는 국물이 웨이팅 타협 이상의 맛을 선사합니다.', 'Yoshiyama Shouten, Sapporo', '11:00', '21:00', null, null, null, null, 60),
  ('sapporo-007', 'sapporo', 'seafood', '스시잔마이 스스키노점 (Sushizanmai)', '스시잔마이 스스키노점 (Sushizanmai)', null, null, null, 'reviewed', '{"스시잔마이 스스키노점 (Sushizanmai)","참치 세트 & 단품 초밥 (세트 약 2,500엔)","Sushizanmai Susukino, Sapporo"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.1', '참치 세트 & 단품 초밥 (세트 약 2,500엔)', '삿포로 유명 스시야들이 대부분 사전 예약제이거나 대기가 일찍 마감됩니다. 스시잔마이는 24시간 영업하여 늦은 밤 야식으로도 웨이팅 없이 신선한 홋카이도 해산물 스시를 맛볼 수 있는 최고의 전천후 대체지입니다.', 'Sushizanmai Susukino, Sapporo', '00:00', '24:00', null, null, null, null, 70),
  ('otaru-001', 'otaru', 'spot', '오타루 운하 (Otaru Canal)', '오타루 운하 (Otaru Canal)', null, null, null, 'reviewed', '{"오타루 운하 (Otaru Canal)","운하 가스등 산책 및 크루즈 탑승 🛥️","Otaru Canal, Otaru"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '운하 가스등 산책 및 크루즈 탑승 🛥️', '일몰 30분 전부터 붉은 노을과 함께 가스등 노란 불빛이 운하를 따라 켜지는 순간이 가장 환상적으로 아름답습니다. 낮보다 밤이 훨씬 아름다운 스팟으로, 옛 벽돌 창고를 개조한 비어홀이나 카페도 함께 둘러보세요.', 'Otaru Canal, Otaru', '00:00', '24:00', null, null, null, null, 10),
  ('otaru-002', 'otaru', 'spot', '오타루 오르골당 (Otaru Music Box Museum)', '오타루 오르골당 (Otaru Music Box Museum)', null, null, null, 'reviewed', '{"오타루 오르골당 (Otaru Music Box Museum)","천상의 오르골 선율 감상 🎶","Otaru Music Box Museum"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '천상의 오르골 선율 감상 🎶', '약 3만여 점에 달하는 아기자기한 오르골이 빛나는 세계 최대 규모의 오르골 전시장입니다. 입구의 상징적인 스팀 증기시계는 15분마다 아름다운 멜로디를 연주하며 증기를 뿜어내니 타이밍에 맞춰 인증샷을 찰칵!', 'Otaru Music Box Museum', '09:00', '18:00', null, null, null, null, 20),
  ('otaru-003', 'otaru', 'seafood', '오타루 도야마 (Otaru Toyama)', '오타루 도야마 (Otaru Toyama)', null, null, null, 'reviewed', '{"오타루 도야마 (Otaru Toyama)","도야마 특선 카이센동 (약 3,500엔)","Otaru Toyama Kaisendon"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '도야마 특선 카이센동 (약 3,500엔)', '오타루역 삼각시장 내부의 타키나미 식당 웨이팅이 시장 밖까지 가득 차 있을 때 탈출할 수 있는 최고의 1선 대체지입니다! 삼각시장 바로 뒤쪽에 위치하며, 재료 신선도와 우니, 게살 토핑 양이 전혀 밀리지 않는 숨은 로컬 강자입니다.', 'Otaru Toyama Kaisendon', '11:00', '18:00', null, null, null, null, 30),
  ('otaru-004', 'otaru', 'seafood', '오타루 마사즈시 운하점 (Masazushi)', '오타루 마사즈시 운하점 (Masazushi)', null, null, null, 'reviewed', '{"오타루 마사즈시 운하점 (Masazushi)","타쿠미 스시 코스 (약 6,500엔)","Otaru Masazushi Zenan"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '타쿠미 스시 코스 (약 6,500엔)', '미스터 초밥왕의 고향 오타루에서 가장 전통 있고 상징적인 대표 스시야입니다. 본관 웨이팅이 길다면 운하점의 아름다운 운하 전망 창가 자리를 노려보는 것을 적극 추천합니다. 이세즈시 대비 예약 난이도가 낮고 캐주얼합니다.', 'Otaru Masazushi Zenan', '11:00', '21:00', null, null, null, null, 40),
  ('otaru-005', 'otaru', 'dessert', '롯카테이 오타루점 (Rokkatei)', '롯카테이 오타루점 (Rokkatei)', null, null, null, 'reviewed', '{"롯카테이 오타루점 (Rokkatei)","슈크림 빵 & 유키콘치즈 (약 150엔~300엔)","Rokkatei Otaru"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.4', '슈크림 빵 & 유키콘치즈 (약 150엔~300엔)', '사카이마치 거리의 르타오(LeTAO) 카페 테이블 웨이팅 대기가 50팀이 넘어갈 때, 바로 옆에 있는 롯카테이 2층 카페 스탠딩석으로 가세요! 갓 구운 바삭한 슈크림 빵을 사면 무료로 원두커피 한 잔을 제공하는 혜택이 있어 가성비 쉼터로 제격입니다.', 'Rokkatei Otaru', '09:00', '18:00', null, null, null, null, 50),
  ('otaru-006', 'otaru', 'dessert', '기타카로 오타루 본점 (Kitakaro)', '기타카로 오타루 본점 (Kitakaro)', null, null, null, 'reviewed', '{"기타카로 오타루 본점 (Kitakaro)","홋카이도 우유 소프트 아이스크림 (약 400엔)","Kitakaro Otaru"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.3', '홋카이도 우유 소프트 아이스크림 (약 400엔)', '르타오 본점 웨이팅 타협을 위한 두 번째 대안! 기타카로 본관 안쪽의 조용하고 고풍스러운 정원에서 아주 진한 정통 홋카이도 목장 우유 맛 아이스크림과 달콤한 바움쿠헨 한 조각을 시켜서 벤치에 앉아 여유롭게 쉴 수 있습니다.', 'Kitakaro Otaru', '09:00', '18:00', null, null, null, null, 60),
  ('tokyo-001', 'tokyo', 'spot', '도쿄 타워 (Tokyo Tower)', '도쿄 타워 (Tokyo Tower)', null, null, null, 'reviewed', '{"도쿄 타워 (Tokyo Tower)","도쿄의 상징 전망대 관람 🗼","Tokyo Tower, Tokyo"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.7', '도쿄의 상징 전망대 관람 🗼', '도쿄의 오랜 랜드마크입니다. 시바 공원에서 도쿄 타워를 배경으로 돗자리를 펴고 피크닉 사진을 찍으면 인생샷을 쉽게 남길 수 있습니다.', 'Tokyo Tower, Tokyo', '09:00', '23:00', null, null, null, null, 10),
  ('tokyo-002', 'tokyo', 'spot', '아사쿠사 센소지 (Senso-ji)', '아사쿠사 센소지 (Senso-ji)', null, null, null, 'reviewed', '{"아사쿠사 센소지 (Senso-ji)","전통 사찰 산책 & 나카미세도리 길거리 간식","Sensoji Temple, Tokyo"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.6', '전통 사찰 산책 & 나카미세도리 길거리 간식', '도쿄에서 가장 오래된 절입니다. 입구의 붉은 거대 등(카미나리몬) 아래서 인증샷을 찍고 사찰 앞 상점가에서 화과자와 모찌를 즐겨보세요.', 'Sensoji Temple, Tokyo', '06:00', '17:00', null, null, null, null, 20),
  ('tokyo-003', 'tokyo', 'spot', '시부야 스카이 (Shibuya Sky)', '시부야 스카이 (Shibuya Sky)', null, null, null, 'reviewed', '{"시부야 스카이 (Shibuya Sky)","전망대 옥상 시부야 스크램블 뷰","Shibuya Sky, Tokyo"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.8', '전망대 옥상 시부야 스크램블 뷰', '시부야 스크램블 스퀘어 빌딩 옥상에 있는 전망대입니다. 일몰 시간대 예약이 가장 인기가 많으며, 바람을 맞으며 360도로 펼쳐진 야경은 장관입니다.', 'Shibuya Sky, Tokyo', '10:00', '22:30', null, null, null, null, 30),
  ('tokyo-004', 'tokyo', 'noodle', '이치란 라멘 신주쿠점', '이치란 라멘 신주쿠점', null, null, null, 'reviewed', '{"이치란 라멘 신주쿠점","천연 돈코츠 라멘 (약 980엔)","Ichiran Shinjuku, Tokyo"}'::text[], '{"혼자"}'::text[], null, 'sapo-curated', null, null, '4.3', '천연 돈코츠 라멘 (약 980엔)', '한국인 입맛에 가장 잘 맞는 1인 독서실 형태의 유명 돈코츠 라멘집입니다. 매운맛 소스 레벨을 4~5단계 정도로 올리면 느끼함 없이 맛있게 드실 수 있습니다.', 'Ichiran Shinjuku, Tokyo', '10:00', '23:00', null, null, null, null, 40),
  ('osaka-001', 'osaka', 'spot', '도톤보리 (Dotonbori)', '도톤보리 (Dotonbori)', null, null, null, 'reviewed', '{"도톤보리 (Dotonbori)","글리코상 인증샷 & 타코야키 투어 🐙","Dotonbori, Osaka"}'::text[], '{"가족","연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.6', '글리코상 인증샷 & 타코야키 투어 🐙', '오사카의 심장 같은 중심가입니다. 거대하고 화려한 입체 간판들을 배경으로 야경을 즐기고, 다리 밑 노점에서 파는 따끈한 타코야키를 맥주와 함께 즐겨보세요.', 'Dotonbori, Osaka', '00:00', '24:00', null, null, null, null, 10),
  ('osaka-002', 'osaka', 'spot', '유니버설 스튜디오 재팬 (USJ)', '유니버설 스튜디오 재팬 (USJ)', null, null, null, 'reviewed', '{"유니버설 스튜디오 재팬 (USJ)","해리포터 & 닌텐도 월드 어트랙션 🎢","Universal Studios Japan, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.8', '해리포터 & 닌텐도 월드 어트랙션 🎢', '아시아 최고의 테마파크 중 하나입니다. 슈퍼 닌텐도 월드에 입장하려면 앱으로 정리권을 꼭 발급받거나 익스프레스 패스를 사전 구매해야 합니다.', 'Universal Studios Japan, Osaka', '08:30', '21:00', null, null, null, null, 20),
  ('osaka-003', 'osaka', 'spot', '교토 기요미즈데라 (청수사)', '교토 기요미즈데라 (청수사)', null, null, null, 'reviewed', '{"교토 기요미즈데라 (청수사)","산등성이에 세워진 목조 사찰 관람 ⛩️","Kiyomizu-dera, Kyoto"}'::text[], '{"가족","연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.7', '산등성이에 세워진 목조 사찰 관람 ⛩️', '오사카에서 당일치기로 다녀오기 좋은 유네스코 세계유산 사찰입니다. 올라가는 언덕길(니넨자카, 산넨자카)의 고즈넉한 목조 건물들과 녹차 아이스크림이 필수 코스입니다.', 'Kiyomizu-dera, Kyoto', '06:00', '18:00', null, null, null, null, 30),
  ('osaka-004', 'osaka', 'meat', '치보 오사카 도톤보리본점', '치보 오사카 도톤보리본점', null, null, null, 'reviewed', '{"치보 오사카 도톤보리본점","치보 도톤보리 오코노미야키 (약 1,650엔)","Chibo Dotonbori, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '치보 도톤보리 오코노미야키 (약 1,650엔)', '철판에 즉석으로 구워주는 도톤보리 정통 오코노미야키 & 야키소바 전문점입니다. 마요네즈 쇼를 눈앞에서 볼 수 있어 눈과 입이 모두 즐겁습니다.', 'Chibo Dotonbori, Osaka', '11:00', '22:00', null, null, null, null, 40),
  ('osaka-005', 'osaka', 'spot', '오사카성 (Osaka Castle)', '오사카성 (Osaka Castle)', null, null, null, 'reviewed', '{"오사카성 (Osaka Castle)","천수각 전망대 & 성곽 공원 산책 🏯","1-1 Osakajo, Chuo Ward, Osaka"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '천수각 전망대 & 성곽 공원 산책 🏯', '오사카의 대표적인 랜드마크입니다. 8층 전망대에서 오사카 시내를 한눈에 내려다볼 수 있으며, 봄에는 벚꽃, 가을에는 단풍 명소로 유명한 거대한 공원이 성을 둘러싸고 있습니다.', '1-1 Osakajo, Chuo Ward, Osaka', '09:00', '17:00', null, null, null, null, 50),
  ('osaka-006', 'osaka', 'spot', '우메다 스카이빌딩 공중정원 (Umeda Sky Building)', '우메다 스카이빌딩 공중정원 (Umeda Sky Building)', null, null, null, 'reviewed', '{"우메다 스카이빌딩 공중정원 (Umeda Sky Building)","360도 야외 루프탑 전망대 야경 관람 🌃","1-1-88 Oyodonaka, Kita Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '360도 야외 루프탑 전망대 야경 관람 🌃', '두 빌딩의 꼭대기가 연결된 독특한 형태의 건물입니다. 야외 루프탑으로 나가면 시원한 바람을 맞으며 환상적인 오사카의 360도 파노라마 야경을 감상할 수 있습니다.', '1-1-88 Oyodonaka, Kita Ward, Osaka', '09:30', '22:30', null, null, null, null, 60),
  ('osaka-007', 'osaka', 'spot', '아베노 하루카스 300 (Harukas 300)', '아베노 하루카스 300 (Harukas 300)', null, null, null, 'reviewed', '{"아베노 하루카스 300 (Harukas 300)","일본 최고층 빌딩 60층 전망대 투어 🏙️","1-1-43 Abenosuji, Abeno Ward, Osaka"}'::text[], '{"연인","가족"}'::text[], null, 'sapo-curated', null, null, '4.7', '일본 최고층 빌딩 60층 전망대 투어 🏙️', '일본에서 가장 높은 빌딩 중 하나인 아베노 하루카스의 58~60층에 위치한 전망대입니다. 바닥부터 천장까지 통유리로 되어 있어 아찔한 높이에서 고베와 교토까지 조망할 수 있습니다.', '1-1-43 Abenosuji, Abeno Ward, Osaka', '09:00', '22:00', null, null, null, null, 70),
  ('osaka-008', 'osaka', 'spot', '신세카이 & 츠텐카쿠 (Shinsekai & Tsutenkaku)', '신세카이 & 츠텐카쿠 (Shinsekai & Tsutenkaku)', null, null, null, 'reviewed', '{"신세카이 & 츠텐카쿠 (Shinsekai & Tsutenkaku)","레트로 오사카 골목 탐방 & 쿠시카츠 맛보기 🗼","1 Ebisu-higashi, Naniwa Ward, Osaka"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.3', '레트로 오사카 골목 탐방 & 쿠시카츠 맛보기 🗼', '1900년대 초반 오사카의 향수가 남아있는 개성 넘치는 레트로 거리입니다. 중심에 솟은 츠텐카쿠 타워와 화려한 화등 간판들 사이에서 원조 쿠시카츠(꼬치튀김)를 즐겨보세요.', '1 Ebisu-higashi, Naniwa Ward, Osaka', '10:00', '20:00', null, null, null, null, 80),
  ('osaka-009', 'osaka', 'spot', '헵파이브 관람차 (HEP FIVE Ferris Wheel)', '헵파이브 관람차 (HEP FIVE Ferris Wheel)', null, null, null, 'reviewed', '{"헵파이브 관람차 (HEP FIVE Ferris Wheel)","우메다 랜드마크 빨간 관람차 탑승 🎡","5-15 Kakudacho, Kita Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '우메다 랜드마크 빨간 관람차 탑승 🎡', '우메다의 쇼핑몰 헵파이브 빌딩 7층에 위치한 지름 75m의 거대한 빨간색 관람차입니다. 블루투스 스피커가 내장되어 있어 좋아하는 음악을 들으며 15분간 도심 전망을 즐길 수 있습니다.', '5-15 Kakudacho, Kita Ward, Osaka', '11:00', '22:45', null, null, null, null, 90),
  ('osaka-010', 'osaka', 'spot', '쿠로몬 시장 (Kuromon Ichiba Market)', '쿠로몬 시장 (Kuromon Ichiba Market)', null, null, null, 'reviewed', '{"쿠로몬 시장 (Kuromon Ichiba Market)","길거리 해산물 구이 & 제철 과일 먹거리 투어 🍣","2-4-1 Nipponbashi, Chuo Ward, Osaka"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.1', '길거리 해산물 구이 & 제철 과일 먹거리 투어 🍣', '오사카의 부엌이라 불리는 190년 전통의 재래시장입니다. 신선한 참치 회, 와규 꼬치구이, 킹크랩 구이 등 다양하고 맛있는 길거리 음식을 즉석에서 맛보는 재미가 쏠쏠합니다.', '2-4-1 Nipponbashi, Chuo Ward, Osaka', '09:00', '18:00', null, null, null, null, 100),
  ('osaka-011', 'osaka', 'seafood', '스시 치하루 (Sushi Chiharu)', '스시 치하루 (Sushi Chiharu)', null, null, null, 'reviewed', '{"스시 치하루 (Sushi Chiharu)","전통 에도마에 스시 코스 🍣","5-12-14 Fukushima, Fukushima Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '전통 에도마에 스시 코스 🍣', '미쉐린 빕구르망에 선정된 가성비 훌륭한 에도마에 스시 전문점입니다. 예약이 필수적이며, 카운터에서 요리사가 직접 쥐어주는 정성스러운 스시를 합리적인 가격에 맛볼 수 있습니다.', '5-12-14 Fukushima, Fukushima Ward, Osaka', '17:00', '23:00', null, null, null, null, 110),
  ('osaka-012', 'osaka', 'meat', '텐동 마키노 (Tempura Makino)', '텐동 마키노 (Tempura Makino)', null, null, null, 'reviewed', '{"텐동 마키노 (Tempura Makino)","붕장어가 통째로 들어간 바삭한 텐동 🍤","3-3-4 Namba, Chuo Ward, Osaka"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.4', '붕장어가 통째로 들어간 바삭한 텐동 🍤', '오사카 난바 지역에서 줄 서서 먹는 유명 텐동 맛집입니다. 주문 즉시 눈앞에서 튀겨내어 겉은 바삭하고 속은 촉촉한 튀김에 특제 소스를 얹어 밥과 함께 먹는 맛이 일품입니다.', '3-3-4 Namba, Chuo Ward, Osaka', '11:00', '21:30', null, null, null, null, 120),
  ('osaka-013', 'osaka', 'meat', '돈카츠 에페 (Epais)', '돈카츠 에페 (Epais)', null, null, null, 'reviewed', '{"돈카츠 에페 (Epais)","저온 조리법으로 익힌 육즙 가득 돈카츠 🥩","1-9-3 Sonezakishinchi, Kita Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '저온 조리법으로 익힌 육즙 가득 돈카츠 🥩', '미쉐린 가이드에 소개된 프리미엄 돈카츠 맛집입니다. 저온에서 천천히 튀겨내 핑크빛이 도는 두툼하고 부드러운 안심 가츠가 대표적이며, 트러플 소금을 찍어 먹는 것이 특징입니다.', '1-9-3 Sonezakishinchi, Kita Ward, Osaka', '11:00', '22:00', null, null, null, null, 130),
  ('osaka-014', 'osaka', 'dessert', '리쿠로 오지상 치즈케이크 (Rikuro Ojisan)', '리쿠로 오지상 치즈케이크 (Rikuro Ojisan)', null, null, null, 'reviewed', '{"리쿠로 오지상 치즈케이크 (Rikuro Ojisan)","갓 구워낸 폭신한 수플레 치즈케이크 🍰","3-2-28 Namba, Chuo Ward, Osaka"}'::text[], '{"가족"}'::text[], null, 'sapo-curated', null, null, '4.5', '갓 구워낸 폭신한 수플레 치즈케이크 🍰', '갓 오븐에서 구워 나올 때 종소리를 울리는 오사카의 대표 디저트 가게입니다. 입안에서 사르르 녹아 없어지는 폭신하고 부드러운 식감이 특징이며 밑부분의 건포도가 단맛을 더해줍니다.', '3-2-28 Namba, Chuo Ward, Osaka', '09:00', '20:00', null, null, null, null, 140),
  ('osaka-015', 'osaka', 'spot', '후시미 이나리 대사 (Fushimi Inari Taisha)', '후시미 이나리 대사 (Fushimi Inari Taisha)', null, null, null, 'reviewed', '{"후시미 이나리 대사 (Fushimi Inari Taisha)","산길을 가득 채운 붉은 센본 토리이 터널 ⛩️","68 Fukakusa Yabunouchicho, Fushimi Ward, Kyoto"}'::text[], '{"가족","연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.7', '산길을 가득 채운 붉은 센본 토리이 터널 ⛩️', '수천 개의 붉은 토리이가 끝없이 이어지는 신비로운 신사입니다. 영화 ''게이샤의 추억'' 촬영지로 유명하며, 산 정상까지 가볍게 트래킹하며 고즈넉한 정취를 만끽할 수 있습니다.', '68 Fukakusa Yabunouchicho, Fushimi Ward, Kyoto', '00:00', '24:00', null, null, null, null, 150),
  ('osaka-016', 'osaka', 'spot', '킨카쿠지 / 금각사 (Kinkaku-ji)', '킨카쿠지 / 금각사 (Kinkaku-ji)', null, null, null, 'reviewed', '{"킨카쿠지 / 금각사 (Kinkaku-ji)","연못 위에 빛나는 찬란한 황금빛 누각 촬영 📸","1 Kinkakujicho, Kita Ward, Kyoto"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.6', '연못 위에 빛나는 찬란한 황금빛 누각 촬영 📸', '2층과 3층 전체가 순금 잎으로 덮여 있는 교토의 상징적인 사찰입니다. 바람이 불지 않는 맑은 날, 거울 같은 연못(교코치)에 비치는 금빛 누각의 투영이 매우 아름답습니다.', '1 Kinkakujicho, Kita Ward, Kyoto', '09:00', '17:00', null, null, null, null, 160),
  ('osaka-017', 'osaka', 'spot', '긴카쿠지 / 은각사 (Ginkaku-ji)', '긴카쿠지 / 은각사 (Ginkaku-ji)', null, null, null, 'reviewed', '{"긴카쿠지 / 은각사 (Ginkaku-ji)","일본 전통 모래 정원과 이끼 정원 산책 툇마루 툇마루","2 Ginkakujicho, Sakyo Ward, Kyoto"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '일본 전통 모래 정원과 이끼 정원 산책 툇마루 툇마루', '화려한 금각사와 달리 소박하고 고즈넉한 매력이 돋보이는 사찰입니다. 하얗게 정돈된 모래 정원(긴샤단)과 울창한 이끼 정원, 그리고 전망대에서 바라보는 은각사 전경이 평화롭습니다.', '2 Ginkakujicho, Sakyo Ward, Kyoto', '08:30', '17:00', null, null, null, null, 170),
  ('osaka-018', 'osaka', 'spot', '아라시야마 치쿠린 대나무숲 (Arashiyama Bamboo Grove)', '아라시야마 치쿠린 대나무숲 (Arashiyama Bamboo Grove)', null, null, null, 'reviewed', '{"아라시야마 치쿠린 대나무숲 (Arashiyama Bamboo Grove)","하늘 높이 솟은 초록빛 대나무 숲길 걷기 🎋","Arashiyama, Ukyo Ward, Kyoto"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '하늘 높이 솟은 초록빛 대나무 숲길 걷기 🎋', '바람이 불 때마다 사각거리는 대나무 소리가 마음을 차분하게 해주는 힐링 스팟입니다. 이른 아침에 방문하면 한적하게 산책을 즐기며 멋진 인생 사진을 남길 수 있습니다.', 'Arashiyama, Ukyo Ward, Kyoto', '00:00', '24:00', null, null, null, null, 180),
  ('osaka-019', 'osaka', 'spot', '기온 하나미코지 거리 (Gion Hanamikoji Street)', '기온 하나미코지 거리 (Gion Hanamikoji Street)', null, null, null, 'reviewed', '{"기온 하나미코지 거리 (Gion Hanamikoji Street)","교토 전통 목조 가옥 골목과 게이샤 풍경 감상 🏮","Gionmachi Minamigawa, Higashiyama Ward, Kyoto"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.4', '교토 전통 목조 가옥 골목과 게이샤 풍경 감상 🏮', '교토의 전통적인 분위기를 고스란히 보존하고 있는 유서 깊은 거리입니다. 어스름한 저녁 시간이 되면 붉은 등불이 켜진 좁은 골목길 사이로 바쁘게 이동하는 게이샤나 마이코를 마주칠 수도 있습니다.', 'Gionmachi Minamigawa, Higashiyama Ward, Kyoto', '00:00', '24:00', null, null, null, null, 190),
  ('osaka-020', 'osaka', 'spot', '교토 니시키 시장 (Nishiki Market)', '교토 니시키 시장 (Nishiki Market)', null, null, null, 'reviewed', '{"교토 니시키 시장 (Nishiki Market)","교토 전통 반찬 & 말차 디저트 시식 투어 🍡","Nakagyo Ward, Kyoto"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.2', '교토 전통 반찬 & 말차 디저트 시식 투어 🍡', '교토의 부엌이라 불리는 400년 역사의 좁고 긴 상업 거리입니다. 달콤한 계란말이, 미니 문어 꼬치, 신선한 모찌와 당당한 말차 아이스크림 등 교토만의 식문화를 즐기기 좋습니다.', 'Nakagyo Ward, Kyoto', '09:30', '18:00', null, null, null, null, 200),
  ('osaka-021', 'osaka', 'spot', '폰토초 골목길 (Pontocho Alley)', '폰토초 골목길 (Pontocho Alley)', null, null, null, 'reviewed', '{"폰토초 골목길 (Pontocho Alley)","카모강 변 목조 식당가에서 저녁 식사 🏮","Pontocho, Nakagyo Ward, Kyoto"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '카모강 변 목조 식당가에서 저녁 식사 🏮', '카모강과 나란히 달리는 좁고 매력적인 등불 골목길입니다. 아기자기한 이자카야와 야키토리 전문점, 그리고 강변을 바라보며 식사할 수 있는 테라스인 ''카와유카''를 경험해 보세요.', 'Pontocho, Nakagyo Ward, Kyoto', '17:00', '23:00', null, null, null, null, 210),
  ('osaka-022', 'osaka', 'meat', '돈카츠 가츠쿠라 삼조본점 (Katsukura Sanjo)', '돈카츠 가츠쿠라 삼조본점 (Katsukura Sanjo)', null, null, null, 'reviewed', '{"돈카츠 가츠쿠라 삼조본점 (Katsukura Sanjo)","바삭하고 고소한 프리미엄 수제 돈카츠 🥩","16 Ishibashicho, Nakagyo Ward, Kyoto"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.5', '바삭하고 고소한 프리미엄 수제 돈카츠 🥩', '교토 삼조 골목 안쪽에 위치한 유명 돈카츠 전문점입니다. 손님이 직접 절구에 깨를 갈아 소스를 만들며, 엄선된 흑돼지 부위를 바삭하게 튀겨내어 기름지지 않고 겉바속촉한 돈카츠를 제공합니다.', '16 Ishibashicho, Nakagyo Ward, Kyoto', '11:00', '21:00', null, null, null, null, 220),
  ('osaka-023', 'osaka', 'noodle', '혼케 오와리야 본점 (Honke Owariya)', '혼케 오와리야 본점 (Honke Owariya)', null, null, null, 'reviewed', '{"혼케 오와리야 본점 (Honke Owariya)","550년 역사의 가문 비법 메밀 소바 🍜","322 Niomontsukinuke-cho, Nakagyo Ward, Kyoto"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.4', '550년 역사의 가문 비법 메밀 소바 🍜', '1465년에 설립되어 황실에도 소바를 납품했던 전통 깊은 가게입니다. 교토의 맑은 우물물로 우려낸 쯔유와 5단 찬합에 정갈하게 나오는 ''호라이 소바''가 대표적이며 고즈넉한 전통 목조 건물에서 식사합니다.', '322 Niomontsukinuke-cho, Nakagyo Ward, Kyoto', '11:00', '19:00', null, null, null, null, 230),
  ('osaka-024', 'osaka', 'dessert', '요지야 카페 기온점 (Yojiya Cafe)', '요지야 카페 기온점 (Yojiya Cafe)', null, null, null, 'reviewed', '{"요지야 카페 기온점 (Yojiya Cafe)","기온 시그니처 캐릭터 마크 말차 라떼 🍵","Gionmachi Kitagawa, Higashiyama Ward, Kyoto"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.2', '기온 시그니처 캐릭터 마크 말차 라떼 🍵', '교토의 전통 화장품 브랜드 요지야에서 운영하는 유명 카페입니다. 요지야 특유의 캐릭터 얼굴이 파우더로 그려져 나오는 쌉싸름하고 달콤한 말차 카푸치노와 녹차 파페를 맛보며 휴식할 수 있습니다.', 'Gionmachi Kitagawa, Higashiyama Ward, Kyoto', '10:00', '19:00', null, null, null, null, 240),
  ('osaka-025', 'osaka', 'meat', '마츠사카규 야키니쿠 M 호젠지 요코초점 (Matsusakagyu Yakiniku M)', '마츠사카규 야키니쿠 M 호젠지 요코초점 (Matsusakagyu Yakiniku M)', null, null, null, 'reviewed', '{"마츠사카규 야키니쿠 M 호젠지 요코초점 (Matsusakagyu Yakiniku M)","마츠사카 프리미엄 와규 세트 (약 8,000엔~12,000엔) 🥩","1-1-19 Namba, Chuo Ward, Osaka"}'::text[], '{"연인","가족"}'::text[], null, 'sapo-curated', null, null, '4.8', '마츠사카 프리미엄 와규 세트 (약 8,000엔~12,000엔) 🥩', '골목 안 고즈넉한 옛 분위기를 보존한 호젠지 요코초에 위치한 최고급 마츠사카 우마 야키니쿠 전문점입니다. 아늑한 개별 룸과 세련된 인테리어로 연인들의 특별한 저녁 데이트 코스로 최적입니다.', '1-1-19 Namba, Chuo Ward, Osaka', '17:00', '23:00', null, null, null, null, 250),
  ('osaka-026', 'osaka', 'dessert', '모토 커피 기타하마점 (Moto Coffee)', '모토 커피 기타하마점 (Moto Coffee)', null, null, null, 'reviewed', '{"모토 커피 기타하마점 (Moto Coffee)","수제 푸딩 & 드립 커피 (약 900엔) ☕","2-1-1 Kitahama, Chuo Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.6', '수제 푸딩 & 드립 커피 (약 900엔) ☕', '오사카 기타하마 강변에 위치해 테라스에서 카모강 같은 토사호리강의 잔잔한 뷰를 바라볼 수 있는 감성 카페입니다. 해질녘 노을과 강바람을 느끼며 디저트를 즐길 수 있는 최고의 데이트 명소입니다.', '2-1-1 Kitahama, Chuo Ward, Osaka', '11:00', '18:00', null, null, null, null, 260),
  ('osaka-027', 'osaka', 'seafood', '스시 사카바 사시스 난바 파크스점 (Sushi Sakaba Sashisu)', '스시 사카바 사시스 난바 파크스점 (Sushi Sakaba Sashisu)', null, null, null, 'reviewed', '{"스시 사카바 사시스 난바 파크스점 (Sushi Sakaba Sashisu)","참치 폭탄 마키 & 단품 초밥 (약 1,500엔~3,000엔) 🍣","2-10-70 Namba-naka, Chuo Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '참치 폭탄 마키 & 단품 초밥 (약 1,500엔~3,000엔) 🍣', '가볍고 캐주얼한 주점 스타일의 가성비 훌륭한 창작 스시 맛집입니다. 참치 뱃살이 넘치도록 들어간 ''토로타쿠마키''와 큼직한 연어 초밥이 시그니처이며, 트렌디한 인테리어로 젊은 연인들의 데이트 코스로 매우 인기가 높습니다.', '2-10-70 Namba-naka, Chuo Ward, Osaka', '11:00', '21:00', null, null, null, null, 270),
  ('osaka-028', 'osaka', 'meat', '아지노야 오코노미야키 (Ajinoya)', '아지노야 오코노미야키 (Ajinoya)', null, null, null, 'reviewed', '{"아지노야 오코노미야키 (Ajinoya)","아지노야 믹스 오코노미야키 (약 1,600엔) 🥞","1-7-16 Namba, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '아지노야 믹스 오코노미야키 (약 1,600엔) 🥞', '미쉐린 빕구르망에 수차례 선정된 도톤보리의 대표적인 오코노미야키 노포입니다. 철판에서 눈앞에 직접 정성스레 구워주는 폭신한 식감의 양배추전과 단짠 특제 소스의 조합은 실패가 없습니다.', '1-7-16 Namba, Chuo Ward, Osaka', '11:00', '22:00', null, null, null, null, 280),
  ('osaka-029', 'osaka', 'meat', '야키니쿠 만료 미나미모리마치점 (Yakiniku Manryo)', '야키니쿠 만료 미나미모리마치점 (Yakiniku Manryo)', null, null, null, 'reviewed', '{"야키니쿠 만료 미나미모리마치점 (Yakiniku Manryo)","생 양념 갈비 & 극상 우설 (약 4,000엔~6,000엔) 🥩","2-3-22 Minamimorimachi, Kita Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.7', '생 양념 갈비 & 극상 우설 (약 4,000엔~6,000엔) 🥩', '오사카 현지인들이 ''가성비 최강 맛집''으로 꼽는 야키니쿠 전문점입니다. 고기 질이 극도로 훌륭하며, 캐주얼하면서도 활기찬 분위기에서 시원한 나마비루와 야키니쿠를 곁들이기 좋습니다. 인기 지점이므로 사전 예약은 필수입니다.', '2-3-22 Minamimorimachi, Kita Ward, Osaka', '17:00', '23:30', null, null, null, null, 290),
  ('osaka-030', 'osaka', 'noodle', '인류 모두 라멘 (Human Beings Everybody Noodles)', '인류 모두 라멘 (Human Beings Everybody Noodles)', null, null, null, 'reviewed', '{"인류 모두 라멘 (Human Beings Everybody Noodles)","라멘 마이크로 & 두툼한 차슈 토핑 (약 1,000엔) 🍜","1-12-17 Minamigata, Yodogawa Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '라멘 마이크로 & 두툼한 차슈 토핑 (약 1,000엔) 🍜', '재미난 상호명과 매장 내부를 가득 채운 미스터 칠드런 음악이 독특한 우메다와 나카하시 근처의 메가 히트 라멘집입니다. 조개 베이스 of 감칠맛 깊은 간장 국물과 도저히 믿기지 않을 정도로 두툼하고 부드러운 차슈 덩어리가 환상적입니다.', '1-12-17 Minamigata, Yodogawa Ward, Osaka', '11:00', '21:30', null, null, null, null, 300),
  ('osaka-031', 'osaka', 'dessert', '하브스 한큐삼번가점 (HARBS)', '하브스 한큐삼번가점 (HARBS)', null, null, null, 'reviewed', '{"하브스 한큐삼번가점 (HARBS)","밀 크레이프 케이크 (약 980엔) 🍰","1-1-3 Shibata, Kita Ward, Osaka"}'::text[], '{"연인","가족"}'::text[], null, 'sapo-curated', null, null, '4.6', '밀 크레이프 케이크 (약 980엔) 🍰', '층층이 얇게 구운 크레이프 사이에 신선한 과일(키위, 바나나, 멜론, 딸기)과 부드러운 커스터드 생크림이 가득 채워진 일본 대표 디저트 브랜드입니다. 케이크 조각이 크고 묵직하여 커피와 곁들여 데이트 중 단것을 보충하기에 완벽합니다.', '1-1-3 Shibata, Kita Ward, Osaka', '10:00', '21:00', null, null, null, null, 310),
  ('osaka-032', 'osaka', 'meat', '미즈노 오코노미야키 (Mizuno)', '미즈노 오코노미야키 (Mizuno)', null, null, null, 'reviewed', '{"미즈노 오코노미야키 (Mizuno)","마 야키 오코노미야키 (약 1,800엔) 🥞","1-4-15 Dotonbori, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '마 야키 오코노미야키 (약 1,800엔) 🥞', '밀가루를 전혀 쓰지 않고 100% 마 전분만으로 반죽하여 속이 극도로 부드럽고 편안한 미쉐린 가이드 수록 노포 맛집입니다. 관자, 돼지고기, 새우가 듬뿍 들어간 ''야마이모야키''가 부동의 대표 메뉴입니다.', '1-4-15 Dotonbori, Chuo Ward, Osaka', '11:00', '22:00', null, null, null, null, 320),
  ('osaka-033', 'osaka', 'dessert', '기타하마 스페이스 링스 (Space Rinku)', '기타하마 스페이스 링스 (Space Rinku)', null, null, null, 'reviewed', '{"기타하마 스페이스 링스 (Space Rinku)","녹차 테린느 & 말차 라떼 (약 1,200엔) 🍵","1-1-29 Kitahama, Chuo Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.4', '녹차 테린느 & 말차 라떼 (약 1,200엔) 🍵', '기타하마 테라스 거리에 위치한 강변 뷰 명소 카페 중 하나입니다. 화이트 톤의 미니멀한 실내 디자인과 나카노시마 공원의 장미정원을 강 건너로 마주 볼 수 있는 로맨틱한 뷰가 인상적입니다.', '1-1-29 Kitahama, Chuo Ward, Osaka', '11:00', '18:00', null, null, null, null, 330),
  ('osaka-034', 'osaka', 'meat', '카츠쿠라 챠야마치 플라자점 (Katsukura)', '카츠쿠라 챠야마치 플라자점 (Katsukura)', null, null, null, 'reviewed', '{"카츠쿠라 챠야마치 플라자점 (Katsukura)","수제 돈카츠 정식 (약 2,200엔) 🥩","19-19 Chayamachi, Kita Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '수제 돈카츠 정식 (약 2,200엔) 🥩', '교토 삼조에 본점을 둔 가츠쿠라의 우메다 챠야마치 지점입니다. 깨끗하고 고급스러운 현대적인 분위기 속에서 바삭한 튀김옷과 쫀득한 식감의 고급 돈카츠를 맛볼 수 있습니다. 샐러드, 밥, 미소시루가 무한 리필됩니다.', '19-19 Chayamachi, Kita Ward, Osaka', '11:00', '21:00', null, null, null, null, 340),
  ('osaka-035', 'osaka', 'dessert', '홉 슈크림 난바본점 (Hop Chou Cream)', '홉 슈크림 난바본점 (Hop Chou Cream)', null, null, null, 'reviewed', '{"홉 슈크림 난바본점 (Hop Chou Cream)","오리지널 커스터드 홉 슈크림 (약 200엔) 🥯","3-2-26 Namba, Chuo Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '오리지널 커스터드 홉 슈크림 (약 200엔) 🥯', '바삭하게 구운 러스크 질감의 슈 껍질 속에 차갑고 달콤한 오리지널 커스터드 크림이 가득 찬 난바의 길거리 디저트 맛집입니다. 주문 즉시 크림을 주입해 겉바속촉의 정석을 보여주며 돌아다니며 가볍게 간식 데이트를 즐기기에 좋습니다.', '3-2-26 Namba, Chuo Ward, Osaka', '10:00', '22:00', null, null, null, null, 350),
  ('osaka-036', 'osaka', 'seafood', '스시 진세이 (Sushi Jinsei)', '스시 진세이 (Sushi Jinsei)', null, null, null, 'reviewed', '{"스시 진세이 (Sushi Jinsei)","셰프 오마카세 스시 디너 (약 15,000엔~20,000엔) 🍣","1-1-18 Shinsaibashisuji, Chuo Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.7', '셰프 오마카세 스시 디너 (약 15,000엔~20,000엔) 🍣', '특별한 기념일이나 조용하고 럭셔리한 데이트를 계획 중이라면 오사카 시내 중심가의 오마카세 명소인 이곳을 추천합니다. 정갈한 원목 카운터 석에서 최고급 식재료로 장인이 선보이는 감동적인 에도마에 스시를 음미할 수 있습니다.', '1-1-18 Shinsaibashisuji, Chuo Ward, Osaka', '17:30', '22:00', null, null, null, null, 360),
  ('osaka-037', 'osaka', 'meat', '아부리야 센니치마에점 (Aburiya)', '아부리야 센니치마에점 (Aburiya)', null, null, null, 'reviewed', '{"아부리야 센니치마에점 (Aburiya)","국산 와규 무제한 타베호다이 코스 (약 4,980엔) 🥩","2-1-17 Sennichimae, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '국산 와규 무제한 타베호다이 코스 (약 4,980엔) 🥩', '테이블 주문 방식으로 신선한 국산 와규 부위와 육회, 식사, 디저트까지 코스로 무제한 주문해 구워 먹는 프리미엄 고기 뷔페입니다. 깔끔하고 쾌적한 개별 부스석으로 연인과 함께 배불리 야키니쿠 데이트를 즐기기에 최적입니다.', '2-1-17 Sennichimae, Chuo Ward, Osaka', '16:00', '22:00', null, null, null, null, 370),
  ('osaka-038', 'osaka', 'meat', '오카루 오코노미야키 (Okaru)', '오카루 오코노미야키 (Okaru)', null, null, null, 'reviewed', '{"오카루 오코노미야키 (Okaru)","오카루 스페셜 오코노미야키 & 캐릭터 마요네즈 아트 (약 1,300엔) 🎨","1-9-19 Sennichimae, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '오카루 스페셜 오코노미야키 & 캐릭터 마요네즈 아트 (약 1,300엔) 🎨', '도라에몽, 헬로키티, 미키마우스 등 갓 구워낸 오코노미야키 위에 셰프님이 현란한 마요네즈 그림을 그려주는 것으로 유명한 이색 노포입니다. 소박한 다다미식 테이블에서 보는 즐거움과 먹는 맛을 동시에 챙길 수 있습니다.', '1-9-19 Sennichimae, Chuo Ward, Osaka', '12:00', '21:30', null, null, null, null, 380),
  ('osaka-039', 'osaka', 'noodle', '카마타케 우동 (Kamatake Udon)', '카마타케 우동 (Kamatake Udon)', null, null, null, 'reviewed', '{"카마타케 우동 (Kamatake Udon)","치쿠타마텐 붓카케 우동 (약 950엔) 🍜","2-1-2 Namba-naka, Chuo Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '치쿠타마텐 붓카케 우동 (약 950엔) 🍜', '오사카 붓카케 우동의 원조로 불리는 면발 맛집입니다. 쫄깃쫄깃하고 탄력 있는 수타 우동 면발에 쯔유를 자작하게 부어 반숙 계란 튀김(타마텐)과 어묵 튀김(치쿠텐)을 터뜨려 슥슥 비벼 먹는 맛이 환상적입니다.', '2-1-2 Namba-naka, Chuo Ward, Osaka', '11:00', '16:00', null, null, null, null, 390),
  ('osaka-040', 'osaka', 'meat', '키타신치 아라타 (Kitashinchi Arata)', '키타신치 아라타 (Kitashinchi Arata)', null, null, null, 'reviewed', '{"키타신치 아라타 (Kitashinchi Arata)","아라타 극상 우설 & 두툼 갈비 야키니쿠 (약 7,000엔~9,000엔) 🥩","1-3-30 Sonezakishinchi, Kita Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '아라타 극상 우설 & 두툼 갈비 야키니쿠 (약 7,000엔~9,000엔) 🥩', '고급 요정들이 즐비한 키타신치 거리에 숨어 있는 아늑하고 프라이빗한 야키니쿠 바입니다. 어둑하고 무드 있는 은은한 조명 아래 카운터 테이블에서 고급 와규 구이와 와인을 분위기 있게 곁들이기 좋은 어른들의 데이트 장소입니다.', '1-3-30 Sonezakishinchi, Kita Ward, Osaka', '18:00', '23:00', null, null, null, null, 400),
  ('osaka-041', 'osaka', 'noodle', '도톤보리 이마이 본점 (Dotonbori Imai)', '도톤보리 이마이 본점 (Dotonbori Imai)', null, null, null, 'reviewed', '{"도톤보리 이마이 본점 (Dotonbori Imai)","키츠네 우동 (약 850엔) 🦊","1-7-22 Dotonbori, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '키츠네 우동 (약 850엔) 🦊', '소란스러운 도톤보리 중심가에서 한적한 일본 정원 입구 같은 고즈넉한 인테리어를 자랑하는 우동 명가입니다. 달콤하고 부드럽게 졸여낸 유부 조각과 홋카이도 다시마로 정성스레 맛을 낸 깔끔한 국물 우동이 대표적입니다.', '1-7-22 Dotonbori, Chuo Ward, Osaka', '11:00', '21:30', null, null, null, null, 410),
  ('osaka-042', 'osaka', 'seafood', '스시 하세가와 신사이바시본점 (Sushi Hasegawa)', '스시 하세가와 신사이바시본점 (Sushi Hasegawa)', null, null, null, 'reviewed', '{"스시 하세가와 신사이바시본점 (Sushi Hasegawa)","하세가와 전통 가이세키 스시 코스 (약 12,000엔~18,000엔) 🍣","1-16-0 Shinsaibashi, Chuo Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '하세가와 전통 가이세키 스시 코스 (약 12,000엔~18,000엔) 🍣', '신사이바시의 조용하고 세련된 미식을 맛볼 수 있는 스시 전문점입니다. 도예 작가의 정갈한 식기에 담겨 나오는 스시와 일식 요리는 예술적이며, 전통과 모던함이 깃든 개별 룸이 잘 갖춰져 있어 조용하게 연인과 식사하기 좋습니다.', '1-16-0 Shinsaibashi, Chuo Ward, Osaka', '17:00', '23:00', null, null, null, null, 420),
  ('osaka-043', 'osaka', 'dessert', '까눌레 뒤 자퐁 (Canele du Japon)', '까눌레 뒤 자퐁 (Canele du Japon)', null, null, null, 'reviewed', '{"까눌레 뒤 자퐁 (Canele du Japon)","오리지널 미니 까눌레 박스 (약 1,200엔) 🧁","2-11-15 Sakuragawa, Naniwa Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '오리지널 미니 까눌레 박스 (약 1,200엔) 🧁', '사쿠라가와 골목 구석에 아기자기하게 자리한 1평 남짓한 테이크아웃 전문 까눌레 가게입니다. 녹차, 흑임자, 호지차 등 일본 전통 식재료를 접목해 겉은 엄청나게 바삭하고 속은 쫀득한 미니 까눌레가 인스타 감성을 자극합니다.', '2-11-15 Sakuragawa, Naniwa Ward, Osaka', '10:00', '19:00', null, null, null, null, 430),
  ('osaka-044', 'osaka', 'meat', '구리야 키타신치 (Kuriya Kitashinchi)', '구리야 키타신치 (Kuriya Kitashinchi)', null, null, null, 'reviewed', '{"구리야 키타신치 (Kuriya Kitashinchi)","야키토리 셰프 코스 & 사케 페어링 (약 6,000엔~8,000엔) 🍢","1-5-7 Sonezakishinchi, Kita Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '야키토리 셰프 코스 & 사케 페어링 (약 6,000엔~8,000엔) 🍢', '일본의 고급 야키토리 문화를 느낄 수 있는 키타신치의 꼬치구이 맛집입니다. 토종닭 부위를 숯불에 세심하게 한 꼬치씩 정성껏 구워내며, 아담하고 조용한 재즈 음악이 나오는 바 공간에서 데이트하기 좋습니다.', '1-5-7 Sonezakishinchi, Kita Ward, Osaka', '17:30', '23:00', null, null, null, null, 440),
  ('osaka-045', 'osaka', 'etc', '나카노시마 Club (Nakanoshima Club)', '나카노시마 Club (Nakanoshima Club)', null, null, null, 'reviewed', '{"나카노시마 Club (Nakanoshima Club)","복고풍 명품 오므라이스 (약 1,100엔) 🍛","1-1-27 Nakanoshima, Kita Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.3', '복고풍 명품 오므라이스 (약 1,100엔) 🍛', '오사카 중앙공회당 지하 1층에 자리한 유서 깊고 아름다운 네오바로크풍 레스토랑입니다. 대정 시대 낭만이 느껴지는 앤틱한 돔 천장 아래서 계란 옷이 얇고 부드러우며 감칠맛 폭발하는 정통 양식 데미글라스 오므라이스를 즐겨보세요.', '1-1-27 Nakanoshima, Kita Ward, Osaka', '11:30', '19:00', null, null, null, null, 450),
  ('osaka-046', 'osaka', 'dessert', '글래시어 에도보리 (Glacier Edobori)', '글래시어 에도보리 (Glacier Edobori)', null, null, null, 'reviewed', '{"글래시어 에도보리 (Glacier Edobori)","수제 피스타치오 젤라또 & 크레페 (약 850엔) 🍦","1-22-1 Edobori, Nishi Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '수제 피스타치오 젤라또 & 크레페 (약 850엔) 🍦', '우츠보 공원 근처에 위치한 트렌디한 프렌치 수제 파티세리 겸 젤라또 가게입니다. 진하고 크리미한 이탈리안 피스타치오와 상큼한 시즌 과일 소르베를 맛보며, 근처 장미공원을 손잡고 느긋하게 산책하기 완벽한 루트입니다.', '1-22-1 Edobori, Nishi Ward, Osaka', '11:00', '19:00', null, null, null, null, 460),
  ('osaka-047', 'osaka', 'seafood', '요시노 스시 (Yoshino Sushi)', '요시노 스시 (Yoshino Sushi)', null, null, null, 'reviewed', '{"요시노 스시 (Yoshino Sushi)","전통 하코스시 (상자초밥 세트, 약 3,000엔) 🍱","3-4-14 Awajimachi, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '전통 하코스시 (상자초밥 세트, 약 3,000엔) 🍱', '180년의 전통을 지닌 오사카 전통 ''하코스시(나무 상자에 밥과 재료를 눌러 만드는 상자초밥)'' 명가입니다. 알록달록한 보석함처럼 도미, 붕장어, 달걀말이가 예쁘게 네모나게 얹어져 나오며 정갈한 일식 도시락 감성을 자극합니다.', '3-4-14 Awajimachi, Chuo Ward, Osaka', '11:00', '19:00', null, null, null, null, 470),
  ('osaka-048', 'osaka', 'dessert', '고칸 요도야바시 본점 (Gokan)', '고칸 요도야바시 본점 (Gokan)', null, null, null, 'reviewed', '{"고칸 요도야바시 본점 (Gokan)","계절 과일 타르트 & 홍차 (약 1,300엔) ☕","2-1-1 Imabashi, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '계절 과일 타르트 & 홍차 (약 1,300엔) ☕', '오래된 은행 건물 대리석 석조 빌딩을 개조하여 1층은 제과점, 2층은 고풍스러운 클래식 살롱 카페로 운영하는 디저트 명가입니다. 트레이에 케이크 샘플을 들고 와 직접 고르게 해주는 황홀한 연출로 여심을 저격하는 정통 데이트 장소입니다.', '2-1-1 Imabashi, Chuo Ward, Osaka', '09:30', '20:00', null, null, null, null, 480),
  ('osaka-049', 'osaka', 'meat', '야키토리 토키토 (Yakitori Tokito)', '야키토리 토키토 (Yakitori Tokito)', null, null, null, 'reviewed', '{"야키토리 토키토 (Yakitori Tokito)","닭 껍질 꼬치 & 닭 완자 츠쿠네 구이 (약 250엔~400엔) 🍢","4-1-3 Nipponbashi, Chuo Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '닭 껍질 꼬치 & 닭 완자 츠쿠네 구이 (약 250엔~400엔) 🍢', '골목 구석에 아늑하게 자리 잡은 고급 카운터석 위주의 야키토리 맛집입니다. 기름기는 쏙 빼고 숯불 향을 은은하게 머금은 부드러운 꼬치를 바로 건네받아 시원한 하이볼와 데이트를 즐기기에 그만입니다.', '4-1-3 Nipponbashi, Chuo Ward, Osaka', '17:00', '23:00', null, null, null, null, 490),
  ('osaka-050', 'osaka', 'dessert', '기타하마 브루클린 로스팅 컴퍼니 (Brooklyn Roasting Company)', '기타하마 브루클린 로스팅 컴퍼니 (Brooklyn Roasting Company)', null, null, null, 'reviewed', '{"기타하마 브루클린 로스팅 컴퍼니 (Brooklyn Roasting Company)","수제 초콜릿 도넛 & 아이스 라떼 (약 900엔) 🍩","2-1-16 Kitahama, Chuo Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '수제 초콜릿 도넛 & 아이스 라떼 (약 900엔) 🍩', '뉴욕 브루클린 감성을 그대로 살린 인더스트리얼 테라스 카페입니다. 넓게 뚫린 목조 테라스 아래로 강물 흐르는 모습을 멍하니 바라보며(물멍) 시원한 에스프레소 음료와 뉴욕식 큰 도넛을 나눠 먹기 좋습니다.', '2-1-16 Kitahama, Chuo Ward, Osaka', '10:00', '20:00', null, null, null, null, 500),
  ('osaka-051', 'osaka', 'noodle', '카도야 식당 (Kadoya Shokudo)', '카도야 식당 (Kadoya Shokudo)', null, null, null, 'reviewed', '{"카도야 식당 (Kadoya Shokudo)","특제 중화 소바 & 찰진 면발 츠케멘 (약 1,200엔) 🍜","4-16-13 Shinmachi, Nishi Ward, Osaka"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '특제 중화 소바 & 찰진 면발 츠케멘 (약 1,200엔) 🍜', '오사카 쇼유 라멘(간장 라멘)의 자존심이자 현지인들이 줄 서는 명가입니다. 윤기가 나고 부드러우며 찰진 식감의 자가제면 국수와 투명하고 깊은 간장 다시마 육수의 조화는 기막히며 라멘 마니아 연인들에게 추천합니다.', '4-16-13 Shinmachi, Nishi Ward, Osaka', '11:00', '17:00', null, null, null, null, 510),
  ('osaka-052', 'osaka', 'seafood', '텐진바시 하루코마 스시 본점 (Harukoma Sushi)', '텐진바시 하루코마 스시 본점 (Harukoma Sushi)', null, null, null, 'reviewed', '{"텐진바시 하루코마 스시 본점 (Harukoma Sushi)","상급 참치 뱃살 초밥 & 우니 초밥 (약 2,000엔~4,000엔) 🍣","5-5-2 Tenjinbashi, Kita Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '상급 참치 뱃살 초밥 & 우니 초밥 (약 2,000엔~4,000엔) 🍣', '일본에서 가장 긴 시장 상점가인 텐진바시스지에 있는 활기찬 대중 초밥집입니다. 가성비가 엄청나며 회 두께가 두껍고 신선합니다. 줄을 서야 하지만 회전율이 빨라 연인과 함께 스시 폭식을 즐기기에 안성맞춤입니다.', '5-5-2 Tenjinbashi, Kita Ward, Osaka', '11:00', '22:00', null, null, null, null, 520),
  ('osaka-053', 'osaka', 'meat', '구시카츠 카츠겐 (Katsugen)', '구시카츠 카츠겐 (Katsugen)', null, null, null, 'reviewed', '{"구시카츠 카츠겐 (Katsugen)","구시카츠 셰프 오마카세 세트 (약 6,000엔~8,000엔) 🍢","1-3-9 Sonezakishinchi, Kita Ward, Osaka"}'::text[], '{"연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '구시카츠 셰프 오마카세 세트 (약 6,000엔~8,000엔) 🍢', '신세카이의 와글와글한 분위기와 달리, 조용하고 품격 있는 바에서 하나씩 갓 튀겨 접시에 내어주는 프리미엄 구시카츠(꼬치튀김) 다이닝입니다. 얇고 가벼운 튀김옷 덕분에 느끼함 없이 우아하게 창작 튀김 데이트를 즐길 수 있습니다.', '1-3-9 Sonezakishinchi, Kita Ward, Osaka', '17:00', '23:00', null, null, null, null, 530),
  ('osaka-054', 'osaka', 'dessert', '카페가루 (Cafe Garb)', '카페가루 (Cafe Garb)', null, null, null, 'reviewed', '{"카페가루 (Cafe Garb)","시폰 케이크 & 하이볼/커피 (약 1,100엔) 🍰","4-4-7 Minamisemba, Chuo Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '시폰 케이크 & 하이볼/커피 (약 1,100엔) 🍰', '미나미센바 쇼핑 타운 한복판에 자리한 4층 규모의 대형 감성 카페이자 비스트로입니다. 모던하고 감각적인 가구 배치와 테라스 가든 공간이 돋보이며, 쇼핑 데이트 후 넓은 소파에서 케이크와 차를 마시며 대화 나누기 최적입니다.', '4-4-7 Minamisemba, Chuo Ward, Osaka', '11:30', '23:00', null, null, null, null, 540),
  ('osaka-055', 'osaka', 'shopping', '신사이바시 파르코 (Shinsaibashi PARCO)', '신사이바시 파르코 (Shinsaibashi PARCO)', null, null, null, 'reviewed', '{"신사이바시 파르코 (Shinsaibashi PARCO)","캐릭터 굿즈 & 트렌디 패션 브랜드 쇼핑 🛍️","1-8-3 Shinsaibashisuji, Chuo Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.6', '캐릭터 굿즈 & 트렌디 패션 브랜드 쇼핑 🛍️', '신사이바시 중심가에 위치한 트렌디한 쇼핑몰입니다. 6층에는 지브리 숍, 짱구 숍, 울트라맨 등 대형 캐릭터 굿즈 매장이 모여 있어 데이트 코스로 필수입니다.', '1-8-3 Shinsaibashisuji, Chuo Ward, Osaka', '10:00', '20:00', null, null, null, null, 550),
  ('osaka-056', 'osaka', 'shopping', '한큐백화점 우메다 본점 (Hankyu Department Store)', '한큐백화점 우메다 본점 (Hankyu Department Store)', null, null, null, 'reviewed', '{"한큐백화점 우메다 본점 (Hankyu Department Store)","명품 손수건 & 갸토 러스크 과자 구매 🎁","8-7 Kakudacho, Kita Ward, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.7', '명품 손수건 & 갸토 러스크 과자 구매 🎁', '오사카 우메다의 대표 백화점입니다. 1층 잡화 매장에서 비비안 웨스트우드 등 명품 손수건을 선물용으로 저렴하게 구매할 수 있고, 지하 식품관 디저트 투어가 인기입니다.', '8-7 Kakudacho, Kita Ward, Osaka', '10:00', '20:00', null, null, null, null, 560),
  ('osaka-057', 'osaka', 'shopping', '루쿠아 오사카 (LUCUA Osaka)', '루쿠아 오사카 (LUCUA Osaka)', null, null, null, 'reviewed', '{"루쿠아 오사카 (LUCUA Osaka)","일본 로컬 스트리트 패션 & 소품 쇼핑 👗","3-1-3 Umeda, Kita Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '일본 로컬 스트리트 패션 & 소품 쇼핑 👗', '우메다역과 직결된 대형 쇼핑몰로, LUCUA와 LUCUA 1100 두 건물로 나뉩니다. 트렌디한 일본 로컬 패션 브랜드와 아기자기 잡화점들이 가득해 연인들의 데이트 쇼핑 장소로 최적입니다.', '3-1-3 Umeda, Kita Ward, Osaka', '10:30', '20:30', null, null, null, null, 570),
  ('osaka-058', 'osaka', 'shopping', '린쿠 프리미엄 아울렛 (Rinku Premium Outlets)', '린쿠 프리미엄 아울렛 (Rinku Premium Outlets)', null, null, null, 'reviewed', '{"린쿠 프리미엄 아울렛 (Rinku Premium Outlets)","해외 명품 & 스포츠 브랜드 아울렛 특가 🏷️","3-28 Rinku-ourai-minami, Izumisano, Osaka"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.4', '해외 명품 & 스포츠 브랜드 아울렛 특가 🏷️', '간사이 공항 바로 직전 정거장에 위치한 대규모 바다 뷰 아울렛입니다. 출국 전이나 귀국 직전에 캐리어를 코인락커에 맡기고 마지막 브랜드 쇼핑을 즐기기 매우 좋습니다.', '3-28 Rinku-ourai-minami, Izumisano, Osaka', '10:00', '20:00', null, null, null, null, 580),
  ('osaka-059', 'osaka', 'shopping', '오사카 포켓몬센터 DX (Pokemon Center DX)', '오사카 포켓몬센터 DX (Pokemon Center DX)', null, null, null, 'reviewed', '{"오사카 포켓몬센터 DX (Pokemon Center DX)","포켓몬 한정판 인형 & 오사카 한정 메달 👾","1-7-1 Shinsaibashisuji, Chuo Ward, Osaka"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.7', '포켓몬 한정판 인형 & 오사카 한정 메달 👾', '신사이바시 다이마루 백화점 9층에 위치한 대형 포켓몬 매장입니다. 오사카 한정판 피카츄 인형과 굿즈가 많아 아이를 동반한 가족이나 키덜트 연인들에게 성지 같은 곳입니다.', '1-7-1 Shinsaibashisuji, Chuo Ward, Osaka', '10:00', '20:00', null, null, null, null, 590),
  ('osaka-060', 'osaka', 'shopping', '오사카 덴덴타운 (Den Den Town)', '오사카 덴덴타운 (Den Den Town)', null, null, null, 'reviewed', '{"오사카 덴덴타운 (Den Den Town)","애니메이션 피규어 & 레트로 게임기 쇼핑 🎮","Nipponbashi, Naniwa Ward, Osaka"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.3', '애니메이션 피규어 & 레트로 게임기 쇼핑 🎮', '도쿄의 아키하바라에 버금가는 오사카의 서브컬처 중심지입니다. 피규어 노점, 레트로 오락기, 중고 CD 숍이 즐비해 덕질을 즐기는 혼자 여행객이나 커플들에게 재미난 볼거리를 제공합니다.', 'Nipponbashi, Naniwa Ward, Osaka', '11:00', '19:00', null, null, null, null, 600),
  ('osaka-061', 'osaka', 'shopping', '난바 파크스 (Namba Parks)', '난바 파크스 (Namba Parks)', null, null, null, 'reviewed', '{"난바 파크스 (Namba Parks)","캐주얼 패션 & 도심 속 루프탑 정원 산책 🌳","2-10-70 Nambanaka, Chuo Ward, Osaka"}'::text[], '{"연인","가족"}'::text[], null, 'sapo-curated', null, null, '4.5', '캐주얼 패션 & 도심 속 루프탑 정원 산책 🌳', '협곡 모양을 본떠 만든 독특하고 아름다운 건축 디자인의 복합 아웃도어 쇼핑몰입니다. 옥상의 거대한 정원 테라스길을 걸으며 힐링 쇼핑 데이트를 즐기기 좋습니다.', '2-10-70 Nambanaka, Chuo Ward, Osaka', '11:00', '21:00', null, null, null, null, 610),
  ('osaka-062', 'osaka', 'shopping', '핸즈 신사이바시점 (Hands)', '핸즈 신사이바시점 (Hands)', null, null, null, 'reviewed', '{"핸즈 신사이바시점 (Hands)","일본 이색 생활 잡화 & 아기자기 디자인 문구 ✏️","3-9-7 Minamisenba, Chuo Ward, Osaka"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.4', '일본 이색 생활 잡화 & 아기자기 디자인 문구 ✏️', '일본 특유의 실용적이고 기발한 생활 아이디어 상품, 뷰티 용품, 고품질 학용품이 층별로 가득한 잡화점입니다. 가벼운 지인 선물을 고르는 재미가 쏠쏠합니다.', '3-9-7 Minamisenba, Chuo Ward, Osaka', '10:00', '21:00', null, null, null, null, 620),
  ('osaka-063', 'osaka', 'shopping', '로프트 우메다점 (Loft Umeda)', '로프트 우메다점 (Loft Umeda)', null, null, null, 'reviewed', '{"로프트 우메다점 (Loft Umeda)","다이어리 꾸미기 스티커 & 캐릭터 콜라보 잡화 🎨","16-7 Chayamachi, Kita Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.6', '다이어리 꾸미기 스티커 & 캐릭터 콜라보 잡화 🎨', '대형 노란색 로고가 상징적인 프리미엄 생활 잡화점의 우메다 플래그십 매장입니다. 시즌 한정 다이어리 꾸미기 문구, 독특한 모바일 액세서리, 코스메틱 매장이 매우 잘 되어 있습니다.', '16-7 Chayamachi, Kita Ward, Osaka', '10:30', '21:00', null, null, null, null, 630),
  ('osaka-064', 'osaka', 'shopping', '프랑프랑 우메다점 (Francfranc)', '프랑프랑 우메다점 (Francfranc)', null, null, null, 'reviewed', '{"프랑프랑 우메다점 (Francfranc)","토끼 주걱 & 예쁜 인테리어 패브릭/식기 🍽️","1-1-3 Shibata, Kita Ward, Osaka"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.5', '토끼 주걱 & 예쁜 인테리어 패브릭/식기 🍽️', '파스텔 톤의 아기자기하고 예쁜 인테리어 소품 브랜드입니다. 시그니처인 토끼 밥주걱, 마카롱 수저받침 등 주방용품이 저렴하고 귀여워 신혼 선물이나 연인 선물용 쇼핑에 제격입니다.', '1-1-3 Shibata, Kita Ward, Osaka', '10:00', '21:00', null, null, null, null, 640),
  ('osaka-065', 'osaka', 'shopping', '돈키호테 도톤보리점 (Don Quijote)', '돈키호테 도톤보리점 (Don Quijote)', null, null, null, 'reviewed', '{"돈키호테 도톤보리점 (Don Quijote)","일본 과자, 메구리즘 안대, 이색 의약품 쇼핑 💊","7-13 Soemoncho, Chuo Ward, Osaka"}'::text[], '{"가족","혼자"}'::text[], null, 'sapo-curated', null, null, '4.1', '일본 과자, 메구리즘 안대, 이색 의약품 쇼핑 💊', '노란 펭귄 캐릭터와 거대한 노란 관람차가 상징적인 오사카 쇼핑의 대명사입니다. 24시간 영업하여 심야 쇼핑에 좋으나 저녁 시간대에는 면세 줄이 엄청나게 길어 새벽이나 이른 아침 방문을 추천합니다.', '7-13 Soemoncho, Chuo Ward, Osaka', '00:00', '24:00', null, null, null, null, 650),
  ('osaka-066', 'osaka', 'shopping', '교토 가와라마치 OPA (Kawaramachi OPA)', '교토 가와라마치 OPA (Kawaramachi OPA)', null, null, null, 'reviewed', '{"교토 가와라마치 OPA (Kawaramachi OPA)","트렌디 유스 의류 & 레트로 스티커사진(프리쿠라) 📸","Shijo-up, Kawaramachi-dori, Nakagyo Ward, Kyoto"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.3', '트렌디 유스 의류 & 레트로 스티커사진(프리쿠라) 📸', '교토 최고의 번화가인 가와라마치에 있는 젊은 층 타겟의 트렌디 쇼핑몰입니다. 일본 고등학생이나 대학생들이 즐겨 찾는 캐주얼 의류 and 소품 숍, 대형 스티커사진 매장이 있어 커플 이색 코스로 추천합니다.', 'Shijo-up, Kawaramachi-dori, Nakagyo Ward, Kyoto', '11:00', '21:00', null, null, null, null, 660),
  ('osaka-067', 'osaka', 'shopping', '교토 다이마루 백화점 (Daimaru Kyoto)', '교토 다이마루 백화점 (Daimaru Kyoto)', null, null, null, 'reviewed', '{"교토 다이마루 백화점 (Daimaru Kyoto)","손수건 선물 & 교토 전통 한정 화과자 선물세트 🍡","79 Tachiuri Nishi-machi, Shimogyo Ward, Kyoto"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '손수건 선물 & 교토 전통 한정 화과자 선물세트 🍡', '역사 깊은 정통 백화점으로 중장년층 선물이나 가족 선물용 손수건, 고급 사케 쇼핑에 적합합니다. 지하 식품관의 교토식 수제 떡(화과자)은 패키징이 정갈하여 귀국 선물로 매우 훌륭합니다.', '79 Tachiuri Nishi-machi, Shimogyo Ward, Kyoto', '10:00', '20:00', null, null, null, null, 670),
  ('osaka-068', 'osaka', 'shopping', '교토 BAL (Kyoto BAL)', '교토 BAL (Kyoto BAL)', null, null, null, 'reviewed', '{"교토 BAL (Kyoto BAL)","블루보틀 커피 & 감성 인테리어 북스토어/잡화 📚","251 Yamazaki-cho, Kawaramachi-dori, Nakagyo Ward, Kyoto"}'::text[], '{"연인","혼자"}'::text[], null, 'sapo-curated', null, null, '4.7', '블루보틀 커피 & 감성 인테리어 북스토어/잡화 📚', '고급스럽고 앤틱하게 인테리어를 꾸며놓은 프리미엄 쇼핑몰입니다. 넓고 차분한 분위기의 블루보틀 매장, 고급 바디케어 브랜드, 감성 편집숍이 모여 있어 차분하게 힐링 데이트 쇼핑을 하기에 최고입니다.', '251 Yamazaki-cho, Kawaramachi-dori, Nakagyo Ward, Kyoto', '11:00', '20:00', null, null, null, null, 680),
