  ('osaka-070', 'osaka', 'shopping', '교토 오르골당 (Kyoto Music Box Museum)', '교토 오르골당 (Kyoto Music Box Museum)', null, null, null, 'reviewed', '{"교토 오르골당 (Kyoto Music Box Museum)","교토 기온 한정판 목조 오르골 & 유리 오르골 🎵","Gionmachi Minamigawa, Higashiyama Ward, Kyoto"}'::text[], '{"연인","가족"}'::text[], null, 'sapo-curated', null, null, '4.5', '교토 기온 한정판 목조 오르골 & 유리 오르골 🎵', '오타루 오르골당의 교토 기온 지점입니다. 기온 거리에 어울리는 고즈넉한 한옥풍 전통 목조 건물 내부에서 잔잔한 오르골 소리를 감상하며 소중한 사람을 위한 특별한 기념품을 고를 수 있습니다.', 'Gionmachi Minamigawa, Higashiyama Ward, Kyoto', '10:00', '18:00', null, null, null, null, 700),
  ('osaka-071', 'osaka', 'shopping', '기온 스나무라 (Gion Sunamura)', '기온 스나무라 (Gion Sunamura)', null, null, null, 'reviewed', '{"기온 스나무라 (Gion Sunamura)","이름을 새겨주는 수제 젓가락 & 전통 목공예 주방 소품 🥢","347-11 Gionmachi Kitagawa, Higashiyama Ward, Kyoto"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '이름을 새겨주는 수제 젓가락 & 전통 목공예 주방 소품 🥢', '교토 기온의 아기자기한 수제 젓가락 전문점입니다. 젓가락을 구매하면 그 자리에서 즉석으로 이름을 무료 각인해 주는 서비스를 제공해 연인 간의 커플 아이템이나 부모님 선물용으로 엄청나게 인기가 많습니다.', '347-11 Gionmachi Kitagawa, Higashiyama Ward, Kyoto', '10:00', '19:00', null, null, null, null, 710),
  ('osaka-072', 'osaka', 'shopping', '니시키 시장 아리츠구 (Aritsugu)', '니시키 시장 아리츠구 (Aritsugu)', null, null, null, 'reviewed', '{"니시키 시장 아리츠구 (Aritsugu)","이름을 새겨주는 장인의 명품 무쇠 부엌칼 🔪","219 Kajiyacho, Nakagyo Ward, Kyoto"}'::text[], '{"혼자","가족"}'::text[], null, 'sapo-curated', null, null, '4.7', '이름을 새겨주는 장인의 명품 무쇠 부엌칼 🔪', '1560년에 창업하여 황실 칼을 제작하던 유서 깊은 대장간입니다. 니시키 시장 골목에 위치하며, 나에게 맞는 수제 칼을 선택하면 장인이 즉석에서 날을 예리하게 세워주고 이름을 각인해 주어 셰프들과 요리 애호가들의 필수 코스입니다.', '219 Kajiyacho, Nakagyo Ward, Kyoto', '09:00', '17:30', null, null, null, null, 720),
  ('osaka-073', 'osaka', 'shopping', '교토 로프트 (Kyoto Loft)', '교토 로프트 (Kyoto Loft)', null, null, null, 'reviewed', '{"교토 로프트 (Kyoto Loft)","교토 한정 디자인 엽서 & 일러스트 소품 엽서 ✉️","58 Mina Kyoto, Nakagyo Ward, Kyoto"}'::text[], '{"혼자","연인"}'::text[], null, 'sapo-curated', null, null, '4.5', '교토 한정 디자인 엽서 & 일러스트 소품 엽서 ✉️', '가와라마치 미나 쿄토 빌딩에 자리한 대형 로프트입니다. 교토의 상징적인 풍경(금각사, 청수사 등)이 수채화로 그려진 시즌 엽서나 교토 한정 스티커, 문구류 코너가 매우 훌륭하여 다꾸 매니아들에게 행복을 줍니다.', '58 Mina Kyoto, Nakagyo Ward, Kyoto', '11:00', '21:00', null, null, null, null, 730),
  ('osaka-074', 'osaka', 'shopping', '교토 가와라마치 디즈니스토어 (Disney Store)', '교토 가와라마치 디즈니스토어 (Disney Store)', null, null, null, 'reviewed', '{"교토 가와라마치 디즈니스토어 (Disney Store)","교토 전통 유카타를 입은 한정판 미키마우스 인형 🐭","3-5 Shinmonzen-cho, Nakagyo Ward, Kyoto"}'::text[], '{"가족","연인"}'::text[], null, 'sapo-curated', null, null, '4.6', '교토 전통 유카타를 입은 한정판 미키마우스 인형 🐭', '교토 가와라마치 시조 거리에 있는 화려한 디즈니 스토어입니다. 교토 지점만의 한정 굿즈(일본 풍 유카타나 기모노를 입은 캐릭터 인형)가 있어 전 세계 컬렉터 커플들이 모여드는 매장입니다.', '3-5 Shinmonzen-cho, Nakagyo Ward, Kyoto', '10:00', '20:00', null, null, null, null, 740)
